WITH deduped AS (SELECT *, RANK() OVER (PARTITION BY segment, country ORDER BY age NULLS LAST) AS rank_in_group FROM customers QUALIFY rank_in_group = 1) SELECT country, CORR(credit_limit, age) AS corr_credit_limit_age, AVG(credit_limit) AS avg_credit_limit, APPROX_PERCENTILE(age, ARRAY(0.25, 0.5, 0.75)) AS age_quartiles, ROUND(SUM(credit_limit) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS credit_limit_per_london, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS age_per_london FROM deduped GROUP BY country;
